/// Avatar hashes of the demo users (the GUI draws them locally).
const AVATARS: [(&str, &str); 2] = [
    ("901", "a1b2c3d4e5f60718293a4b5c6d7e8f90"),
    (ME, "1234abcd5678ef901234abcd5678ef90"),
];

fn user(id: &str, username: &str, name: &str) -> User {
    let avatar = AVATARS.iter().find(|(u, _)| *u == id).map(|(_, h)| *h);
    serde_json::from_value(json!({"id": id, "username": username, "global_name": name, "avatar": avatar}))
        .unwrap()
}

fn msg(id: u64, channel: &str, author: &User, minutes_ago: i64, content: &str) -> Message {
    let ts = (Local::now() - Duration::minutes(minutes_ago)).to_rfc3339();
    serde_json::from_value(json!({
        "id": id.to_string(), "channel_id": channel, "content": content, "timestamp": ts,
        "author": {"id": author.id, "username": author.username, "global_name": author.global_name, "avatar": author.avatar},
    }))
    .unwrap()
}

pub fn messages() -> Vec<(String, Vec<Message>)> {
    let giulia = user("901", "giulia.dev", "Giulia");
    let marco = user("902", "marco_ops", "Marco");
    let me = user(ME, "tommaso", "Tommaso");

    let mut general = vec![
        msg(
            60001,
            "1001",
            &marco,
            26 * 60,
            "Has anyone tried the new kernel on the NAS?",
        ),
        msg(
            60002,
            "1001",
            &giulia,
            26 * 60 - 2,
            "Yes, no problems with ZFS so far",
        ),
        msg(
            60003,
            "1001",
            &marco,
            95,
            "Folks, VPN maintenance tonight from 10 to 11 pm",
        ),
        msg(60004, "1001", &marco, 94, "Also posted in <#1004>"),
        msg(
            60005,
            "1001",
            &giulia,
            40,
            "<@900> I saw your Rust client! How much RAM does it use compared to the official one? \
             I'm trying to figure out whether it's worth it on my old 4 GB laptop too.",
        ),
        msg(
            60006,
            "1001",
            &me,
            35,
            "No Chromium behind it, it starts in a moment 🙂 I'll measure it properly",
        ),
        msg(60007, "1001", &me, 34, "Next step is rendering images"),
        msg(60008, "1001", &giulia, 3, "Fantastic <:ferris:123456789>"),
    ];
    general.sort_by(|a, b| a.id.cmp(&b.id));
    // A real mention (to highlight it), a reply, an attachment and reactions.
    general[4].mentions = vec![me.clone()];
    general[5].referenced_message = Some(Box::new(
        serde_json::from_value(json!({
            "id": "60005", "content": general[4].content.clone(),
            "author": {"id": &giulia.id, "username": &giulia.username, "global_name": &giulia.global_name}
        }))
        .unwrap(),
    ));
    // In the demo the image is not downloaded: the GUI recognises the
    // `demo://` address and generates it on the fly.
    general[6].attachments = serde_json::from_value(json!([{
        "id": "1", "filename": "gui-preview.png", "size": 245_760,
        "url": DEMO_IMAGE_URL, "content_type": "image/png", "width": 960, "height": 600
    }]))
    .unwrap();
    general[7].reactions = serde_json::from_value(json!([
        {"count": 2, "me": true, "emoji": {"id": null, "name": "🦀"}},
        {"count": 1, "me": false, "emoji": {"id": null, "name": "🚀"}}
    ]))
    .unwrap();
    // A link to a GIF: Discord turns it into a `gifv` embed.
    let mut gif = msg(
        60009,
        "1001",
        &marco,
        2,
        "https://tenor.com/view/ferris-dance-demo",
    );
    gif.embeds = serde_json::from_value(json!([{
        "type": "gifv", "url": "https://tenor.com/view/ferris-dance-demo",
        "provider": {"name": "Tenor"},
        "thumbnail": {"url": DEMO_GIF_URL, "width": 320, "height": 200},
        "video": {"url": "demo://ferris.mp4", "width": 320, "height": 200}
    }]))
    .unwrap();
    general.push(gif);

    let help = vec![msg(
        61001,
        UNREAD_CHANNEL,
        &giulia,
        10,
        "How do you handle the gateway resume after a disconnection?",
    )];

    let dm = vec![
        msg(70001, "5001", &giulia, 60, "Hi! Did you push the login branch?"),
        msg(70010, "5001", &me, 58, "Yes, the QR code is in too"),
    ];

    vec![
        ("1001".to_string(), general),
        (UNREAD_CHANNEL.to_string(), help),
        ("5001".to_string(), dm),
    ]
}

const DEMO_GIF_PAGE: &str = "https://klipy.com/gifs/ferris-demo-";

/// Picker GIFs in the demo: all the same local animation.
pub fn gif_results(query: &str) -> Vec<GifResult> {
    let query = query.trim();
    let count = if query.is_empty() { 6 } else { 3 };
    (1..=count)
        .map(|i| GifResult {
            url: format!("{DEMO_GIF_PAGE}{i}"),
            src: DEMO_GIF_URL.to_string(),
            title: format!("Ferris {i}"),
            width: 320,
            height: 200,
        })
        .collect()
}

/// Embed Discord would add to the link of a demo GIF.
pub fn gif_embed(content: &str) -> Option<Embed> {
    if !content.starts_with(DEMO_GIF_PAGE) {
        return None;
    }
    serde_json::from_value(json!({
        "type": "gifv", "url": content, "provider": {"name": "Klipy"},
        "thumbnail": {"url": DEMO_GIF_URL, "width": 320, "height": 200},
        "video": {"url": "demo://ferris.mp4", "width": 320, "height": 200}
    }))
    .ok()
}

/// Message created locally when something is sent in demo mode.
pub fn local_message(
    channel_id: &str,
    author: Option<User>,
    content: &str,
    existing: Option<&Vec<Message>>,
) -> Message {
    let next_id = existing
        .and_then(|v| v.last())
        .and_then(|m| m.id.parse::<u64>().ok())
        .unwrap_or(80_000)
        + 1;
    let author = author.unwrap_or_else(|| user("902", "marco_ops", "Marco"));
    msg(next_id, channel_id, &author, 0, content)
}
